// Generated by rspack_rails __RSPACK_RAILS_VERSION__. Do not edit: `bin/rails rspack:build` (which
// runs before assets:precompile and tests) and `bin/rails rspack:sync` rewrite
// this file when the gem changes. Customize the config in rspack.config.mjs.
// Checksum: __RSPACK_RAILS_CHECKSUM__ (tells a hand edit from an older version)
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { defineConfig } from "@rspack/cli";

export const VERSION = "__RSPACK_RAILS_VERSION__";

const self = fileURLToPath(import.meta.url);
// The Rails app: this file lives in <root>/config/rspack/.
export const root = path.resolve(path.dirname(self), "../..");
// `rspack serve` and its aliases (`rspack dev`, `rspack server`, `rspack s`).
export const isDevServer = process.argv.slice(2).some((arg) => ["serve", "dev", "server", "s"].includes(arg));
export const isProduction =
  !isDevServer &&
  (process.env.RAILS_ENV === "production" || process.env.NODE_ENV === "production");
// Bundle analysis (bin/rails rspack:analyze): a production build into
// tmp/rsdoctor, plus a single-file Rsdoctor report next to it.
export const analyze = process.env.RSDOCTOR === "true";

const packageJson = readJson(path.resolve(root, "package.json"));
warnIfStale();

// The rspack config for this Rails app. Pass a function to change it; it gets
// the config and { root, isDevServer, isProduction, analyze }, and returns the
// config (or changes it in place and returns nothing):
//
//   export default railsConfig((config, { isProduction }) => {
//     config.resolve.alias = { "@": path.resolve("app/javascript") };
//     return config;
//   });
export async function railsConfig(customize = (config) => config) {
  const config = await baseConfig();
  const env = { root, isDevServer, isProduction, analyze };
  return defineConfig((await customize(config, env)) ?? config);
}

async function baseConfig() {
  // React Fast Refresh under `rspack serve`, once rspack:install:react added the plugin.
  const reactRefresh = isDevServer && hasPackage("@rspack/plugin-react-refresh");
  const { ReactRefreshRspackPlugin } = reactRefresh ? await import("@rspack/plugin-react-refresh") : {};

  // Browser support for JS and CSS output: the app's browserslist config
  // (.browserslistrc, or "browserslist" in package.json) when it has one,
  // otherwise Baseline "widely available".
  const browsers = hasBrowserslistConfig() ? "browserslist" : "browserslist:baseline widely available";

  // React Compiler (https://react.dev/learn/react-compiler), opt-in. Set
  // RSPACK_REACT_COMPILER=true for every build, including assets:precompile.
  const reactCompiler = process.env.RSPACK_REACT_COMPILER === "true";

  // Type errors in the dev server overlay, once rspack:install:typescript added
  // ts-checker-rspack-plugin. Builds leave type checking to `typecheck`.
  const typeCheck = isDevServer && hasPackage("ts-checker-rspack-plugin");
  const { TsCheckerRspackPlugin } = typeCheck ? await import("ts-checker-rspack-plugin") : {};

  const { RsdoctorRspackPlugin } = analyze ? await import("@rsdoctor/rspack-plugin") : {};
  const analyzeDir = path.resolve(root, "tmp/rsdoctor");

  // Views are rendered by Rails, so hot updates cannot change them: under
  // `rspack serve`, editing a view or helper reloads the page instead.
  // RSPACK_VIEW_RELOAD=false turns that off.
  const viewDirs =
    process.env.RSPACK_VIEW_RELOAD === "false"
      ? []
      : ["app/views", "app/helpers", "app/components"]
          .map((dir) => path.resolve(root, dir))
          .filter((dir) => fs.existsSync(dir));

  // Keep these in sync with RspackRails.config (same env vars, same defaults).
  const host = process.env.RSPACK_DEV_SERVER_HOST || "localhost";
  const port = Number(process.env.RSPACK_DEV_SERVER_PORT || 3036);

  const entry = entries();
  const outputPath = analyze ? path.join(analyzeDir, "build") : path.resolve(root, "app/assets/builds");

  return {
    context: root,
    mode: isProduction ? "production" : "development",
    target: ["web", browsers],
    // Production builds ship no source maps (they would expose your source in
    // public/assets). Set RSPACK_DEVTOOL to override, e.g. "hidden-source-map"
    // for an error tracker, or "false" to turn them off in development too.
    devtool: devtool(),
    // Reuse work across builds and dev server restarts (node_modules/.cache/rspack).
    // Edits to rspack.config.mjs, this file, package.json, the lockfile,
    // tsconfig.json or .browserslistrc start a fresh cache.
    cache: {
      type: "persistent",
      buildDependencies: buildDependencies(),
      // Options read from the environment change the output too.
      version: JSON.stringify({ reactCompiler, browsers }),
      // `rspack serve` compiles with HMR (import.meta.webpackHot is true), a
      // build without. One cache per kind, or the dev server would reuse a
      // build's modules and hot updates would fall back to full reloads.
      name: isDevServer ? "serve" : isProduction ? "production" : "development",
    },
    entry,
    // Under `rspack serve`, every entry on a page shares one runtime
    // (runtime.js, added by the helpers). Two runtimes on one page break HMR:
    // the second one takes over the hot update callback of the first.
    optimization: { runtimeChunk: isDevServer ? { name: "runtime" } : false },
    // Rspack's size hints flag any entry over 244 KiB, which an app with React
    // and Turbo passes on day one, so every deploy printed a warning nobody
    // could act on. `bin/rails rspack:analyze` shows what is in a bundle.
    // Turn them back on with config.performance = { hints: "warning" }.
    performance: { hints: false },
    output: {
      path: outputPath,
      filename: "[name].js",
      // ".digested" tells Propshaft the file is already fingerprinted.
      chunkFilename: "[name]-[contenthash].digested.js",
      // CSS imported from JavaScript. ".bundle" avoids clashing with
      // app/assets/stylesheets/application.css in Propshaft.
      cssFilename: "[name].bundle.css",
      cssChunkFilename: "[name]-[contenthash].digested.css",
      // Images and fonts imported from JS or CSS url(), also fingerprinted by rspack.
      assetModuleFilename: "[name]-[contenthash].digested[ext]",
      // Under `rspack serve`, Rails proxies /rspack/ to the dev server
      // (RspackRails::DevServerProxy), so bundles, chunks, workers and hot
      // updates are same-origin with the page. Otherwise "auto": JS finds chunks
      // and images next to its own script (any assets prefix or asset_host), and
      // CSS uses relative url()s that Propshaft resolves and rewrites.
      publicPath: isDevServer ? "/rspack/" : "auto",
      // Each build deletes what earlier builds left behind (old chunks, a
      // development build's source maps), which Propshaft would otherwise copy
      // to public/assets. Only rspack's own files: output of other tools
      // (cssbundling, tailwindcss-rails) stays. Not under `rspack serve`: its
      // hot updates live in memory, and the next build does the cleaning.
      clean: !isDevServer && { keep: (file) => !removable(file, outputPath, Object.keys(entry)) },
    },
    resolve: {
      extensions: ["...", ".ts", ".jsx", ".tsx"],
      // Bare imports of app code work as they did with importmap
      // (import "controllers/application", import "lib/utils").
      modules: ["node_modules", path.resolve(root, "app/javascript")],
      // "paths" aliases from tsconfig.json (e.g. "@/*": ["app/javascript/*"]).
      tsConfig: fs.existsSync(path.resolve(root, "tsconfig.json")) ? path.resolve(root, "tsconfig.json") : undefined,
    },
    module: {
      rules: [
        {
          // TypeScript and JSX through Rspack's built-in SWC (no type checking).
          test: /\.(ts|jsx|tsx)$/,
          exclude: /node_modules/,
          loader: "builtin:swc-loader",
          options: {
            detectSyntax: "auto",
            jsc: {
              transform: {
                react: { runtime: "automatic", development: !isProduction, refresh: reactRefresh },
                // Only when on: Rspack 2.0 rejects the option (added in 2.1).
                ...(reactCompiler && { reactCompiler: true }),
              },
            },
          },
          type: "javascript/auto",
        },
        {
          // Images and fonts: inlined below 8 KB, emitted as files above.
          test: /\.(png|jpe?g|gif|svg|webp|avif|ico|woff2?|ttf|otf|eot)$/i,
          type: "asset",
        },
        {
          // Native CSS; *.module.css files become CSS modules.
          test: /\.css$/,
          type: "css/auto",
          // Tailwind CSS v4 (bin/rails rspack:install:tailwind). Files without
          // Tailwind directives pass through untouched.
          use: hasPackage("@tailwindcss/webpack")
            ? [{ loader: "@tailwindcss/webpack", options: { base: root } }]
            : [],
        },
        // Sass (bin/rails rspack:install:sass); *.module.scss are CSS modules.
        // app/assets/stylesheets is a load path, as with dartsass-rails.
        ...(hasPackage("sass-loader")
          ? [
              {
                test: /\.s[ac]ss$/,
                type: "css/auto",
                loader: "sass-loader",
                options: { sassOptions: { loadPaths: [path.resolve(root, "app/assets/stylesheets")] } },
              },
            ]
          : []),
      ],
    },
    // url("/icon.png") in CSS points at public/ or a Propshaft path
    // (/assets/...), served by Rails: keep it as written. Rspack 2 would
    // otherwise look for /icon.png at the root of the file system and fail.
    externals: [keepRootRelativeUrls],
    // `rspack serve` compiles dynamic import()s on first use. The client
    // posts to /rspack/_rspack/lazy/trigger on the page's origin, and Rails
    // proxies it to the dev server (RspackRails::DevServerProxy), so it works
    // wherever the page does. RSPACK_LAZY_COMPILATION=false compiles everything upfront.
    lazyCompilation:
      isDevServer && process.env.RSPACK_LAZY_COMPILATION !== "false"
        ? { imports: true, entries: false, serverUrl: "/rspack/" }
        : false,
    plugins: [
      reactRefresh && new ReactRefreshRspackPlugin(),
      typeCheck && new TsCheckerRspackPlugin(),
      !isDevServer && removeDevServerRuntime,
      writeManifest,
      analyze &&
        new RsdoctorRspackPlugin({
          disableClientServer: true,
          // controllers/autoload and components/mount are side-effect imports by design.
          linter: { rules: { "tree-shaking-side-effects-only": "off" } },
          output: { mode: "brief", reportDir: analyzeDir, options: { type: ["html"] } },
        }),
    ].filter(Boolean),
    // Tailwind watches the whole app for class names. Skip directories that
    // Rails and rspack itself write to, or every write triggers a rebuild.
    watchOptions: {
      ignored: ["node_modules", ".git", "log", "tmp", "storage", "public", "coverage", "app/assets/builds"]
        .map((dir) => `${root.replaceAll("\\", "/")}/${dir}/**`),
    },
    devServer: {
      host,
      port,
      hot: true,
      // Keep app/assets/builds current while the dev server runs, so Propshaft
      // (and `stylesheet_link_tag :app`) never serve a stale bundle. Hot update
      // files stay in memory so they never reach public/assets.
      // Served from the root; Rails strips /rspack/ when it proxies.
      devMiddleware: { publicPath: "/", writeToDisk: (file) => !/\.hot-update\./.test(file) },
      watchFiles: viewDirs,
      allowedHosts: "all",
      headers: { "Access-Control-Allow-Origin": "*" },
      client: {
        webSocketURL: webSocketURL(host, port),
        overlay: true,
      },
    },
  };
}

// Entries: app/javascript/application.{js,ts,jsx,tsx} plus every file in
// app/javascript/entrypoints/, named after the file (admin.js -> "admin").
// Restart the dev server after adding an entrypoint.
function entries() {
  const entry = {};
  for (const ext of ["js", "ts", "jsx", "tsx"]) {
    const file = `./app/javascript/application.${ext}`;
    if (!entry.application && fs.existsSync(path.resolve(root, file))) entry.application = file;
  }
  const entrypointsDir = path.resolve(root, "app/javascript/entrypoints");
  if (fs.existsSync(entrypointsDir)) {
    for (const file of fs.readdirSync(entrypointsDir).sort()) {
      const match = file.match(/^(.+)\.(js|ts|jsx|tsx|css|scss|sass)$/);
      if (!match) continue;
      // admin.js and admin.css side by side make one entry with both.
      const files = [entry[match[1]], `./app/javascript/entrypoints/${file}`].flat().filter(Boolean);
      entry[match[1]] = files.length === 1 ? files[0] : files;
    }
  }
  return entry;
}

function devtool() {
  const value = process.env.RSPACK_DEVTOOL;
  if (value === "false") return false;
  if (value) return value;
  return isProduction ? false : "cheap-module-source-map";
}

// The HMR websocket is the one connection that skips Rails: the browser opens
// it to the dev server itself. Behind a forwarded port or a TLS proxy
// (Codespaces, a remote dev container), RSPACK_DEV_SERVER_PUBLIC_URL is the dev
// server's URL as the browser sees it, e.g. https://myapp-3036.app.github.dev.
function webSocketURL(host, port) {
  const value = process.env.RSPACK_DEV_SERVER_PUBLIC_URL;
  if (!value) return `ws://${host}:${port}/ws`;
  let url;
  try {
    url = new URL(value);
  } catch {
    throw new Error(`[rspack_rails] RSPACK_DEV_SERVER_PUBLIC_URL is not a URL: ${value}`);
  }
  url.protocol = { "http:": "ws:", "https:": "wss:" }[url.protocol] ?? url.protocol;
  if (url.pathname === "/") url.pathname = "/ws";
  return url.toString();
}

function readJson(file) {
  return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, "utf8")) : {};
}

function hasPackage(name) {
  const { dependencies = {}, devDependencies = {} } = packageJson;
  return name in dependencies || name in devDependencies;
}

function hasBrowserslistConfig() {
  return fs.existsSync(path.resolve(root, ".browserslistrc")) || "browserslist" in packageJson;
}

// After `bundle update rspack_rails`, the next rspack:build rewrites this file.
// Until then, say so when rspack runs on its own (bin/dev, npm run build).
function warnIfStale() {
  const lockfile = path.resolve(root, "Gemfile.lock");
  if (!fs.existsSync(lockfile)) return;
  const locked = fs.readFileSync(lockfile, "utf8").match(/^ {4}rspack_rails \(([^)]+)\)$/m)?.[1];
  if (locked && locked !== VERSION) {
    console.warn(
      `[rspack_rails] config/rspack/rails.mjs is from rspack_rails ${VERSION}, but Gemfile.lock has ${locked}. ` +
        "Run `bin/rails rspack:sync` to update it.",
    );
  }
}

function keepRootRelativeUrls({ request, dependencyType }, callback) {
  if (dependencyType === "url" && request.startsWith("/") && !request.startsWith("//")) {
    return callback(null, request, "asset");
  }
  callback();
}

// Whether output.clean may delete this path. Rspack passes absolute paths
// when it scans the output directory and paths relative to it for the assets
// of an earlier compilation under --watch, which may be gone already.
// Directories are not kept, so stale chunks in subdirectories go too.
function removable(file, outputPath, entryNames) {
  const absolute = path.resolve(outputPath, file);
  let directory = false;
  try {
    directory = fs.lstatSync(absolute).isDirectory();
  } catch {
    // Already deleted: nothing to keep.
  }
  return directory || ownOutput(path.relative(outputPath, absolute), entryNames);
}

// Whether rspack wrote this file in app/assets/builds, by the same rule as
// RspackRails::Entrypoints.outputs (rspack:clobber): an entry's script and
// extracted CSS, the dev server's runtime, their source maps, the
// fingerprinted chunks, images and fonts, and the manifest.
function ownOutput(file, entryNames) {
  const name = file.replaceAll("\\", "/");
  if (name.includes(".digested.") || name === ".rspack-manifest.json") return true;
  return [...entryNames, "runtime"].some((entryName) =>
    [`${entryName}.js`, `${entryName}.bundle.css`].some((own) => name === own || name === `${own}.map`),
  );
}

// `rspack serve` writes runtime.js next to entries that need it. A normal
// build makes self-contained entries, so drop the dev server's runtime and
// the helpers stop linking it.
const removeDevServerRuntime = {
  apply(compiler) {
    const remove = () => {
      for (const file of ["runtime.js", "runtime.js.map"]) {
        fs.rmSync(path.join(compiler.options.output.path, file), { force: true });
      }
    };
    compiler.hooks.beforeRun.tap("RemoveDevServerRuntime", remove);
    compiler.hooks.watchRun.tap("RemoveDevServerRuntime", remove);
  },
};

// .rspack-manifest.json next to the bundles (RspackRails::Manifest): for each
// entry, the scripts and stylesheets the view helpers link, runtime first.
//   { "entries": { "print": { "js": [], "css": ["print.bundle.css"], "stylesheetOnly": true } } }
// `rspack serve` writes .rspack-dev-manifest.json instead, which the helpers
// read while it runs: a build alongside it (`bin/rails test` runs one) leaves
// it alone, so dev pages keep linking runtime.js. Not in ownOutput, so a
// build's clean keeps it.
const manifestName = isDevServer ? ".rspack-dev-manifest.json" : ".rspack-manifest.json";
const writeManifest = {
  apply(compiler) {
    const name = "RspackRailsManifest";
    const { Compilation, sources } = compiler.rspack;
    compiler.hooks.thisCompilation.tap(name, (compilation) => {
      compilation.hooks.processAssets.tap({ name, stage: Compilation.PROCESS_ASSETS_STAGE_REPORT }, () => {
        const entries = {};
        // Files a script entry needs, such as a runtime chunk shared through
        // optimization.runtimeChunk: never deleted with a stylesheet-only entry's script.
        const needed = new Set();
        for (const [entryName, entrypoint] of compilation.entrypoints) {
          if (!stylesheetEntry(compiler, entryName)) entrypoint.getFiles().forEach((file) => needed.add(file));
        }
        for (const [entryName, entrypoint] of compilation.entrypoints) {
          const runtime = new Set(entrypoint.getRuntimeChunk()?.files ?? []);
          const files = entrypoint.getFiles().filter((file) => !file.includes(".hot-update."))
            .sort((a, b) => runtime.has(b) - runtime.has(a));
          const stylesheetOnly = stylesheetEntry(compiler, entryName);
          let js = files.filter((file) => file.endsWith(".js"));
          // A stylesheet-only entry needs a script only under `rspack serve`, for
          // hot updates. Rspack 2.0 still emits an empty one in builds: drop it.
          if (stylesheetOnly && !isDevServer) {
            js.filter((file) => !needed.has(file)).forEach((file) => compilation.deleteAsset(file));
            js = [];
          }
          entries[entryName] = { js, css: files.filter((file) => file.endsWith(".css")), stylesheetOnly };
        }
        compilation.emitAsset(manifestName, new sources.RawSource(`${JSON.stringify({ entries }, null, 2)}\n`));
      });
    });
  },
};

// Built from CSS alone (app/javascript/entrypoints/print.css).
function stylesheetEntry(compiler, entryName) {
  const imports = compiler.options.entry[entryName]?.import ?? [];
  return imports.length > 0 && imports.every((file) => /\.(css|scss|sass)$/.test(file));
}

// Files whose changes invalidate the persistent cache: both config files,
// package.json and the lockfile, tsconfig.json and .browserslistrc.
function buildDependencies() {
  return [self, "rspack.config.mjs", "rspack.config.js", "rspack.config.ts",
    "package.json", "package-lock.json", "yarn.lock", "pnpm-lock.yaml", "bun.lock", "bun.lockb",
    "tsconfig.json", ".browserslistrc"]
    .map((file) => path.resolve(root, file))
    .filter((file) => fs.existsSync(file));
}
